import numpy as np
from rcb_hb import Session
import mujoco as mj
from scipy.spatial.transform import Rotation
class Controller:
 def __init__(self,s):
  self.s=s;self.m=s.model;self.d=s.data;m=self.m;d=self.d
  self.k=m.actuator_gainprm[:,0].copy();self.kv=-m.actuator_biasprm[:,2].copy()
  self.jids=m.actuator_trnid[:,0];self.qids=m.jnt_qposadr[self.jids];self.vids=m.jnt_dofadr[self.jids]
  self.base=d.qpos[:7].copy();self.q0=d.qpos.copy();self.ct0=self.targets()
  self.feet=[m.body(x+'_ankle_link').id for x in ['left','right']]
  self.fpos=[d.xpos[b].copy() for b in self.feet];self.frot=[d.xmat[b].reshape(3,3).copy() for b in self.feet]
  self.ikd=mj.MjData(m)
 def targets(self):
  d=self.d;m=self.m
  c=d.qpos[self.qids].copy()
  for i in range(m.nu):
   if m.actuator_trntype[i]==3:c[i]=d.ten_length[self.jids[i]]
  return c
 def action(self,c):return np.clip(2*(c-self.m.actuator_ctrlrange[:,0])/np.diff(self.m.actuator_ctrlrange,axis=1)[:,0]-1,-1,1)
 def hold(self):return self.action(self.ct0)
if __name__=='__main__':
 s=Session('kitchen',instance='/app/instance.npz');c=Controller(s)
 for t in range(200):
  s.step(c.hold())
  if t%20==0:print(t,s.data.qpos[:7])
PY
