from control import *
def smooth(t):return np.clip(t,0,1)**2*(3-2*np.clip(t,0,1))
def walk(c,t):
 p=c.base[:3].copy();p[2]=.965;fp=np.array(c.fpos);R=Rotation.from_quat(c.base[[4,5,6,3]]).as_matrix();fr=np.array(c.frot)
 # shift towards right foot, left step, shift towards left, right step, center
 p0=p.copy();pR=np.r_[fp[1,:2],.965];pR[:2]+=[-.005,.025]
 dest=fp.copy()+[-.1,.45,0]
 pL=np.r_[dest[0,:2],.965];pL[:2]+=[.005,.025]
 pend=p0+[-.1,.45,0]
 if t<40:p=p0+(pR-p0)*smooth(t/40);sup=(0,1)
 elif t<80:
  z=(t-40)/40;fp[0]=c.fpos[0]+(dest[0]-c.fpos[0])*smooth(z);fp[0,2]+=.13*np.sin(np.pi*z);p=pR;sup=(1,)
 elif t<130:
  fp[0]=dest[0];p=pR+(pL-pR)*smooth((t-80)/50);sup=(0,1)
 elif t<170:
  z=(t-130)/40;fp[0]=dest[0];fp[1]=c.fpos[1]+(dest[1]-c.fpos[1])*smooth(z);fp[1,2]+=.13*np.sin(np.pi*z);p=pL;sup=(0,)
 else:fp=dest;p=pL+(pend-pL)*smooth((t-170)/40);sup=(0,1)
 return c.wbc(basepos=p,footpos=fp,support=sup)
if __name__=='__main__':
 s=Session('kitchen',instance='/app/instance.npz');c=Controller(s)
 with s.recording() as rec:
  for t in range(250):
   s.step(walk(c,t))
   if t%10==0:print(t,np.round(s.data.qpos[:3],3),np.round(s.data.qvel[:3],2),flush=True)
 s.save_trajectory(rec.actions,'/app/output/walk.npz')
